cd /tmp && adb shell input tap 700 1728 && sleep 1 && adb exec-out uiautomator dump /dev/tty 2>/dev/null | grep -oE '<node[^>]*CheckBox[^>]*>' | grep -oE 'checked="[^"]*"' | paste -s -; adb exec-out uiautomator dump /dev/tty 2>/dev/null | grep -oE '<node[^>]*EditText[^>]*>' | grep -oE 'text="[^"]*"|bounds="[^"]*"' | paste - - | tail -1; adb shell input tap 700 2600; sleep 0.8; adb shell input text "Headache%ssince%syesterday,%sadvised%srest"; sleep 0.5; adb shell input keyevent KEYCODE_BACK; sleep 0.8; adb exec-out uiautomator dump /dev/tty 2>/dev/null | grep -oE '<node[^>]*EditText[^>]*>' | grep -oE 'text="[^"]*"' | tail -1; adb shell input tap 1220 2816; sleep 5; echo "== screen after submit"; python3 -I ui.py show; echo "== ANC logs"; adb logcat -d | grep -E ' ANC ' | grep -vE 'Alphabetic'; echo "== crashes"; adb logcat -d | grep -E 'FATAL|AndroidRuntime: .*Exception' | head -3; echo "== server"; curl -s 'http://localhost:8080/fhir/Encounter?patient=anc-patient-3&_summary=count' | grep total; curl -s 'http://localhost:8080/fhir/QuestionnaireResponse?patient=anc-patient-3' | python3 -c "
import json,sys; d=json.load(sys.stdin); print('QR total', d.get('total'))
for e in d.get('entry',[]):
  r=e['resource']; print(' status',r.get('status'),'subject',r.get('subject'),'encounter',r.get('encounter'),'questionnaire',r.get('questionnaire'))
  def walk(items):
    for i in items:
      print('  ',i['linkId'], [list(a.values())[0] for a in i.get('answer',[])]); walk(i.get('item',[]))
  walk(r.get('item',[]))"; curl -s 'http://localhost:8080/fhir/Observation?patient=anc-patient-3&date=2026-10-13' | python3 -c "import json,sys; d=json.load(sys.stdin); print('obs today:', d.get('total')); [print(' ',e['resource']['code']['coding'][0]['code'], e['resource'].get('valueQuantity',{}).get('value'), [c['valueQuantity']['value'] for c in e['resource'].get('component',[])], e['resource'].get('subject'), e['resource'].get('encounter')) for e in d.get('entry',[])]"

